{
float height;
cout<< "Enter your height: " <<endl; // output stream
cin>> height; // input stream
if (height <= 0)
{
cerr<< "You entered an invalid height!" <<endl;
exit(1);
}
cout<< "Your height is " << height << " feet" <<endl;
getch();
return 0;
}

